package com.vandorlabs.neoforge.screen;
import com.vandorlabs.screen.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Blocks;
/** Loaded native identities exercise the world adapter separately from frozen topology goldens. */
final class ScreenGroupChecks {
 static void run(ServerLevel level,java.util.Map<ScreenFamily,NativeScreenBlock> blocks){int checks=0;for(var family:ScreenFamily.values()){var block=blocks.get(family);var root=new BlockPos(4320+family.ordinal()*16,100,4320);var state=block.defaultBlockState();var basis=ScreenJoinGeometry.basis(family,block.screenState(state),false);var tiles=new java.util.ArrayList<NativeScreenEntity>();for(int y=0;y<2;y++)for(int x=0;x<2;x++){var pos=root.offset(x*basis.dx(0)+y*basis.dx(2),x*basis.dy(0)+y*basis.dy(2),x*basis.dz(0)+y*basis.dz(2));level.getChunkAt(pos);level.setBlock(pos,state,2);var tile=(NativeScreenEntity)level.getBlockEntity(pos);var data=new CompoundTag();new NativeScreenActivation(com.vandorlabs.persistence.DisplayActivationData.LEGACY.withMode(2)).write(data);tile.loadWithComponents(data,level.registryAccess());tiles.add(tile);}var origin=tiles.get(0);boolean joins=ScreenJoinGeometry.supports(family,false);int count=joins?4:1;need(NativeScreenGroups.editMembers(origin).size()==count&&NativeScreenGroups.powerMembers(origin).size()==count,"actual loaded rectangle "+family);checks++;var targets=NativeScreenGroups.editMembers(origin);var before=targets.stream().map(NativeScreenEntity::screenSettings).toList();var edit=new NativeScreenActivationEdit(1,3,0,2,1,true);var denied=targets.get(targets.size()-1);need(!NativeScreenGroups.applyActivation(origin,edit,tile->tile!=denied),"whole-group permission denial "+family);for(int i=0;i<targets.size();i++)need(targets.get(i).screenSettings()==before.get(i),"denied group changes no settings "+family);checks++;ScreenBlockChecks.changedObserver=tile->{for(var target:targets)need(target.screenSettings().activation().data().mode==1&&target.screenSettings().inverted(),"observer sees complete activation group "+family);need(!NativeScreenGroups.applyActivation(origin,edit,t->true),"group publication refuses editor reentry "+family);};try{need(NativeScreenGroups.applyActivation(origin,edit,tile->true),"authorized complete group "+family);}finally{ScreenBlockChecks.changedObserver=null;}checks++;var other=tiles.get(3);var changed=other.saveWithoutMetadata(level.registryAccess());changed.putBoolean("RedstoneInverted",false);other.loadWithComponents(changed,level.registryAccess());need(NativeScreenGroups.editMembers(origin).size()==count,"inversion does not disconnect authored edit band "+family);need(NativeScreenGroups.powerMembers(other).size()==1,"inversion separates local power band "+family);checks+=2;level.setBlock(origin.getBlockPos(),Blocks.AIR.defaultBlockState(),2);need(NativeScreenGroups.editMembers(origin).equals(java.util.List.of(origin)),"stale owner cannot discover current members "+family);checks++;for(var tile:tiles)level.setBlock(tile.getBlockPos(),Blocks.AIR.defaultBlockState(),2);}System.out.println("Native Screen loaded group adapter PASS checks="+checks+" no channel receiver power read");}
 private static void need(boolean value,String why){if(!value)throw new AssertionError(why);}
}
